 {'idx': 15, 'is_supporting': False, 'paragraph_text': 'Avoca was a small town in Avoca Township, located in southeastern Pottawatomie County, Oklahoma Territory. The post office was established in 1894 and closed permanently in 1906.', 'title': 'Avoca, Oklahoma'}
 {'idx': 16, 'is_supporting': False, 'paragraph_text': 'Sabin is an unincorporated community in the Town of Sylvan, Richland County, Wisconsin, United States. It is located at the intersection of County Highway E and Robbson Drive.', 'title': 'Sabin, Wisconsin'}
 {'idx': 17, 'is_supporting': False, 'paragraph_text': 'KAvZ is a subsidiary of Russian Buses which is a subsidiary of GAZ Group. Starting in 2015, the GAZ Group has introduced a single brand for all its bus manufacturing subsidiaries, and newly manufactured vehicles now feature the deer badge of the GAZ company.', 'title': 'KAvZ'}
 {'idx': 18, 'is_supporting': False, 'paragraph_text': 'Champlain is a municipality, located in Les Chenaux Regional County Municipality and the administrative region the Mauricie, in the province of Quebec, Canada. Located on the north shore of St. Lawrence River, Champlain is also part of the metropolitan area of Trois-Rivières.', 'title': 'Champlain, Quebec'}
